UPDATE directory
SET is_valid = 0, invalidated_at = SYSUTCDATETIME(), invalid_reason = 'HIS_NOT_RETURNED',
    updated_at = SYSUTCDATETIME()
FROM md_hospital_directory directory
WHERE directory.organization_id = #{organizationId}
  AND directory.source_system_code = 'PRIMARY_HIS'
  AND directory.directory_type = #{directoryType.code}
  AND directory.is_valid = 1
  AND directory.latest_batch_id <> #{batchId}

